B('06超人集团',[
C('alpha','阿尔法博士','阿尔法博士是德国科学家，也是超人集团的最高领袖，拥有多门学科的博士头衔。他把少数人的知识优势解释成统治所有人的资格，集合科学家、武装人员和秘密设施，准备以先进火箭逼各国屈服。木兰花偶然从快艇上将他俘走，搜出软管手枪与假护照，丢掉器物之后，他的学位并不能帮助他摆脱近身控制；漂到荒岛时，他还不得不接受自己看轻的东方女性带他游泳上岸。可是科技并未完全失去作用，他曾改进船上的热探测器，故意配合生火，让同伴循热源赶来。救援者用能弯曲弹道的麻醉武器绕过人质掩蔽，他重新掌握主动，既赞赏木兰花，又不肯接受她拒绝加入，决定送她去学习组织语言。其宏大计划仍有未完成的燃料研究，海底发电厂又是所有飞行基地的共同依赖；木兰花最终借萨都拉舰队摧毁这一根本设施，失电的平台先后坠落。原文只交代集团失去总部、许多成员尚存，没有单独核实他的尸体。终局不能让他随身重建全套基地，更不能把未完成的首都毁灭计划当作可随意发动的攻击；他保有的是科学知识、精英统治信念及其在现实条件前暴露的局限。','集团总部与海底供能设施被毁，空中基地陆续失电坠落；阿尔法个人生死未单独确认。','德国男子，身材比木兰花肥大，态度倨傲，谈及科研与统治时得意。','以少数人的科学优势建立统治秩序，吸纳他认定有价值的人。','先以知识和身份压人；身体受制时依赖协作与设备反转。','多学科研究、热探测器改进及科技组织规划；个人普通肉身，终局无完整供能网络。',[(902,984,'被俘、武器被弃及身体局限'),(1034,1108,'热探测救援与首领身份'),(1122,1150,'未完成火箭、强制招募与无线供能'),(2346,2358,'总部毁灭与平台失电')],[('遇到有能力而拒绝服从的人','认定对方属于自己的精英阶层','会把赞赏变成强制吸纳，难以承认对方另有价值选择。'),('脱离设备处在自然环境','自己的身体技能不足','被迫接受实际可行的援助，同时寻找知识能重新发挥作用的条件。'),('大型计划依赖同一能源设施','只关注设备性能优势','容易低估共同基础设施被攻击后的连锁失效。')],roles=['反派'],scores={'physical':1,'energy':0,'scope':0,'sustain':1,'range':0,'combat':1},tier='纸',limits='个人原有软管手枪被木兰花丢入海中；总部供能和飞行平台已毁。研究知识须有材料、加工、协作者和时间才能转为装备，不提供无条件重建。未完成火箭的威胁不计常态战力。',uncertainties=['个人生死没有独立确认；集团大部分成员尚存不能证明他本人一定生还。'],reasons={'physical':'被木兰花轻易制住，个人没有超人肉身。','energy':'科技供能依靠已毁设施，并非身体产生能量。','scope':'终局按个人作用范围，未把集团全球计划计成个人攻击。','sustain':'普通身体，科研需要外部设施；无无限供能。','range':'个人手枪已被抛海，不默认补发。','combat':'能利用探测器与接应翻盘，但近身明显不及木兰花。'}),
C('zhedaoer','哲道尔博士','哲道尔博士是一位头发斑白的语言专家，参与创造世界语，在公开消息里早因飞机失事而死去，实际却出现在超人集团的海底学校中担任校长。他为组织创造专用语言，使成员能够在外界面前交流而不易被理解，也把学习这门语言当成新人加入的第一步。木兰花被带到学校时，他率同学列队欢迎，解释大家呼喊的是欢迎词，握手、自我介绍，并以先进教学方法和舒适住宿说明这里并不像普通牢房。他说一个月可以掌握新语言，也强调室内空气与气压经过精细调节；然而这些热情与待遇并没有给被强制带来的人真正离开的自由，木兰花很快发现房门、通气管和海底位置共同构成囚禁。哲道尔并未亲自展示枪战或读心，语言造成的信息壁垒来自陌生知识与训练，绝不是说出几个词便能支配意志。总部供能体系被毁后，学校作为原有组织设施不能自动保留，博士个人结局也没有逐一交代。角色的矛盾在于他可以真诚欣赏学习与文明统一，却在服务精英统治的制度中，把对方未曾同意的训练当成礼貌欢迎；此前的死亡消息只是公开记录，不能据此给他复活能力。','海底学校及集团总体设施受总部毁灭事件影响，个人生死未明；先前飞机失事死亡消息已被本人现身否定。','头发斑白的老年人，礼貌握手，像热情的学者与校长。','为超人集团建立共同语言，教育被吸纳的成员。','用讲解、欢迎仪式与舒适待遇推进训练，忽略被招募者是否同意。','语言构造、教学与辨认；学习仍需过程，不提供万能翻译或精神控制。',[(1186,1218,'学校、真实现身、语言和教学'),(1220,1252,'环境实际构成囚禁'),(2346,2358,'集团供能体系毁灭')],[('新来者不理解组织语言','对方被视作未来成员','主动解释并安排学习，把不懂看作可解决的知识问题。'),('被招募者抗拒待遇优厚的学校','本人已认同组织目标','可能误把拒绝理解成暂时不适应，而漏看其自由选择。'),('需要跨群体保密交流','有时间训练共同词汇','建立实际语言体系，不把术语变成魔法。')],roles=['反派'],uncertainties=['原文未核实其最终个人生死；一个月掌握语言是其教学承诺而非已完整演示。']),
C('sen_limei','森里美','森里美以从菲律宾来的商人身份在城市活动，与法南度同住滨海新村的住宅，表面交易在警方初查中没有问题，后来入境证件却被证实伪造。他们所属的超人集团有自己的语言、秘密升降机和沿海交通体系，日常富裕外表掩盖了与外界隔绝的协作网络。开篇狗被车碾死，两人对老妇仆人大发雷霆，在泥土血迹中急切寻找狗身上失落的东西，其中一人动手打人；老妇中毒后，他们强调没有碰过她，警方不能立即认定如何下毒。叙述在这场骚乱中没有逐一标明两人的分工，因此不能将每一记殴打、每次搜寻或未经证实的下毒都独占归到森里美身上。后来木兰花被送到海底学校，瘦削的森里美明确现身，自报姓名、礼貌引路，脸上却几乎不露可供判断的表情。他由街头粗暴事件转为程序化的接引者，显示敌对机构也能借礼节维持控制。终局总部毁去，个人下落未写；他的化名掩护、隐秘联络与带路权限仍有可演绎价值，但不自动继承组织全部科技或在陌生世界拥有那座学校。','最后明确出场是引导木兰花进入海底学校；集团总部后被毁，个人结局未写。','十分瘦削的东方男子，衣着名贵，接引时礼貌而少表情。','维持超人集团的秘密行动与人员转运。','公开场合急于处理泄密风险；机构内部按程序礼貌引导。','商人身份掩护、组织语言和秘密通道接引；武装设施须实际在场。',[(32,152,'两名商人的共同街头行为，未区分全部动作'),(416,430,'姓名与住处'),(760,766,'假入境证件'),(1184,1190,'本人自报身份与接引')],[('隐秘物件在公众场合丢失','旁人不知道其真正价值','会显出与普通财物不相称的焦急，泄露行动异常。'),('新俘虏已被安排进入组织','自己负责转运接引','维持礼貌而不解释去向之外的细节。'),('真实身份可能受到查验','仍有提前准备的社会外衣','依靠证件与商业表象拖延，不能假定能骗过深入调查。')],roles=['反派'],scores={'physical':1,'energy':0,'scope':0,'sustain':1,'range':0,'combat':2},tier='纸',confidence='medium',uncertainties=['开篇及住宅中若干场面没有区分森里美与法南度，不能把所有动作重复确认为两人的个人战绩。']),
C('fanandu','法南度','法南度与森里美作为一对商人在城市落脚，住在滨海新村同一住宅，身份资料起初能通过普通商业调查，却在更深入的检索中被发现入境证件全是假造。他们与一名老妇仆人及一条狗出现在街头事故里，狗死后两人急于寻找丢失的东西，为此不顾名贵衣服沾满血污泥土，又对仆人责骂，其中一人殴打她，另一人忙于检查死狗。老妇随后在众目睽睽下中毒身亡，两人以没有身体接触抗议拘留；如何使她中毒，正文并未最终证明。后面的秘密住宅显示这对商人的住处连接庞大地下设施，警方赶到时却找不到足以说服情报机构的痕迹，外界甚至怀疑调查者想象出整批敌人。法南度的单独面貌和最后行动没有像森里美那样再次明确点名，这份不足必须保留，而不能用同伙后来引路的情节填给他。可以可靠归纳的是参与隐蔽据点活动、在公共事故中急于挽回组织损失，以及依靠非公开语言与伪造身份遮蔽真实关系。总部最终毁灭后，个人是否生还未写；原先的社会掩护也不等于到了任何地方都能自然取得合法身份。','集团据点转移后无单独点名结局；总部后来被毁，个人生死未知。','名贵衣着的东方男子，具体哪一名对应开篇两人的全部动作未交代。','保护超人集团的秘密据点和失落物件，避免身份暴露。','面对意外泄密显得急躁，对公开追查坚持表面合法说辞。','身份伪装、秘密语言、据点协作；缺乏可单独核验的超常武器使用表现。',[(32,152,'与同伙共同参与事故与争执'),(212,224,'初查身份和毒死疑点'),(416,430,'姓名与住所'),(760,766,'据点清除和证件伪造')],[('偶然事故可能暴露秘密物件','有公众围观而不能公开解释','优先搜寻物件，可能因急躁暴露重视程度。'),('警察要求说明可疑死亡','没有直接接触的可见证据','强调行为表面以争取离开的空间。'),('据点已引来持续调查','组织具撤离准备','依靠转移和清除痕迹，而非与警方公开交战。')],roles=['反派'],scores={'physical':1,'energy':0,'scope':0,'sustain':1,'range':0,'combat':1},tier='纸',confidence='medium',uncertainties=['原文不区分开篇两人的每项动作；不宣称他施毒、独自击伤丁培或使用某件特定武器。']),
C('jialubin','嘉路宾','嘉路宾是超人集团游艇上的武装头目，身形壮硕，鹰钩鼻，靠残忍与压迫维持上下关系。他得知木兰花将来可能归自己指挥，先表示不欢迎这样的部下，又试图掌掴她；木兰花抓腕踢腹，把他摔下船，令他的权威在众人面前受挫。他爬回艇上，借其他人的枪口控制她，准备以羞辱报复，却被腕表通讯中上级的命令制止，愤怒仍不得不服从。随后木兰花、高翔、穆秀珍拒绝加入，他设计用鲜肉引来虎鲨，将三人推海处死，亲自站在后面押送，得意嘲弄所谓东方三剑侠为什么失去气概。他没有想到看似垂头的三人早用敲击暗号协调，接近船舷反而把施刑者送到柔道最适合反制的距离；三人突然转身，将他和两名押送者抛入自己引来的鲨群。海中立即出现大片血水，船上开枪杀鲨救援，具体遗体没有检验，正文按已很难生还处理。人物的残酷并不等于无畏，他落海的惨叫揭示了同样的求生恐惧；鲨鱼只是由食物诱来的野生危险，既不受他意念控制，也会反过来攻击他。','被木兰花摔入自己招来的虎鲨群，严重遇袭；按原文情境极可能死亡，未有独立尸检。','壮硕、鹰钩鼻的男子，常露傲慢与残忍笑容；中东外貌是叙述观感。','维护指挥地位、报复羞辱者，以恐惧迫人服从。','先动手立威，受挫后借群体枪口报复，仍受上级命令约束。','普通格斗、携带枪械与部下押送；可用鲜肉引鲨但不控制鲨鱼。',[(1406,1444,'立威失败、武器与上级制止'),(1484,1496,'拒绝入伙与引鲨处决'),(1554,1626,'押送、反摔和鲨袭')],[('新来者不肯接受自己指挥','以为有群体武力保障','用羞辱或掌掴立威，容易低估其近身反击。'),('报复欲与上级命令冲突','上级仍有实际控制权','愤怒但暂时收手，再寻找获准的报复方式。'),('准备以环境危险处刑','亲自贴近仍有行动能力的俘虏','可能把自己放进同一危险范围。')],roles=['反派'],scores=GUN,tier='并',revive=True,uncertainties=['死亡高度符合场面与叙述判断，但原文没有单独核验遗体；回溯部署仅为可用版本。']),
C('superman_yacht_chief','超人集团游艇上的匿名上级','这位只通过传音设备露出身份的上级，统辖嘉路宾所在游艇，声音明确不同于集团最高首领阿尔法，不能将两人合并。他能从监视设备掌握甲板上的冲突，在嘉路宾准备羞辱木兰花时发令制止，显示他并不任由下属随意处置有价值的俘虏。可是这种克制不是尊重自由：三位被俘者坐进舱房之后，他隔着传音器参与谈话，听见穆秀珍低声抱怨，便用科学超人的自信回应，并以他们仍是俘虏反驳她的挑战。当木兰花明确拒绝加入，他毫不掩饰地说明集团行动尚未发动，她已经知道太多，只能被灭口；仍给半小时考虑，以死亡期限逼人改变选择。他接受嘉路宾的引鲨办法，又说这种方法称不上科学，仿佛区分手段是否先进比受害者的命运更值得讨论。三人后来反制押送者，潜回艇上藏到靠岸，他的具体反应和最终个人结局没有揭示。可演绎的是透过设备掌握信息、压住下属、以强迫吸纳与灭口维持秘密的管理逻辑；监视有真实布置范围，不意味着全知，后续总部毁灭也不能给他留下凭空召回的组织。','俘虏逃走后不再单独出现；集团总部后来被毁，个人生死不明。','外貌没有展示，以不同于阿尔法的声音和艇上指挥关系辨认。','保护集团秘密并吸纳有能力的外人，避免下属浪费有价值目标。','隔设备监视与交涉，拒绝加入则给出最后期限并允许灭口。','预设影音监视、传音联络和艇上指挥；未显示个人武器及格斗能力。',[(1430,1444,'腕表命令及并非阿尔法的声音'),(1470,1496,'监听、招募与灭口期限'),(1720,1732,'俘虏实际脱身')],[('下属因私怨准备伤害重要俘虏','自己仍想利用其能力','先制止个人报复，把处置权收回。'),('被控制者明确拒绝加入','其已获知关键秘密','把选择压缩成服从或死亡，并以期限施压。'),('远程监视让自己感觉掌握全局','忽略设备之外的藏身处与无声联络','可能漏掉俘虏在已知环境中的逃路。')],roles=['反派'],uncertainties=['姓名、外貌和最终生死未知；不能与阿尔法或其他书的无名首脑合并。']),
C('zhang_boatman','超人集团游艇上的张姓成员','张姓成员在超人集团游艇上工作，具体职位与全名未写，至少承担带路和照料救生艇的任务。木兰花被嘉路宾威胁时，他按上级命令把她带离，途中用中国话提醒她不要再激怒这个残忍的人，既给了她善意警告，又不断强调自己不能多谈。她追问姓氏，他惶恐地说出姓张便退开；同属一个组织没有使他必然赞同所有暴行，与陌生俘虏之间也能出现有限的关切。后来三位俘虏把押送者摔进鲨群，躲在盖着帆布的救生艇里，他例行拉帆布时摸到人，揭开便看见他们。木兰花原想出手，认出他后停住，他也迅速盖回帆布，没有呼喊告密，只因紧张大口喘气。两人用摩斯电码敲击交谈，他起初认为他们没有逃路，劝其出来，木兰花要求他只当没看见，他最终告知游艇要去近岸港口并走开。三人得以趁夜离船，他没有再被单独提及。角色的道德动作是一次明确的默许与情报帮助，不能因此假定他早有全面反叛计划，也不能继续把他当作无条件执行灭口命令的机器。','未揭发救生艇中的三位俘虏，告知目的港后离开；后续下落未知。','中国男子，常显惶恐，秘密帮助别人时呼吸急促。','在组织中保全自己，同时尽可能避免眼前人遭残酷伤害。','先低声警告，帮助时尽量保持隐蔽、限制自己的暴露。','船上日常工作、摩斯电码和有限路线信息；不掌握整个组织机密。',[(1436,1452,'警告、姓氏与恐惧'),(1658,1706,'发现藏身者、敲码与默许逃离')],[('同伴准备对俘虏施暴','自己不能公开违抗','可能用警告和带离提供有限缓冲。'),('意外发现本可告发的逃亡者','对方愿相信自己的善意','可以选择不声张，而非自动邀功。'),('帮助对方需要的只是少量信息','透露后尚可不直接卷入交战','用隐蔽渠道说明真实条件，不保证其必能逃脱。')],roles=['阶段性对立者','转为救助者']),
C('general_mei','梅将军','梅将军是本地总参谋长，出场时是一位身材矮胖、脾气出名急躁的老将。高翔经历超人集团囚禁与爆炸后，请方局长紧急召集军政首脑和各国外交人员，想让所有国家先相信威胁再联合行动；梅将军却不接受仅凭个人讲述就调动国家力量。他带两名秘书来到会议室，首先质问为什么通过最高元首通知自己，听到秘密科学集团、空中火箭场和可能摧毁各国首都的说法，便反问讲述者是否做恶梦或看多了科幻电影。要求证据本身有其职责理由，但他随即把尚未得到证实当成荒唐失职，宣布会议有损国际体面，要求警务总监处分相关人员，带头离场；外交人员的哄笑随之使高翔与穆秀珍无法继续说明。木兰花预先料到这种反应，后来只能保持自己已死的假象，私下向真正信任她的萨都拉求援，另行摧毁威胁。梅将军未被写成与超人集团勾结的内奸，也没有见到最终证据后继续否认的情节。他是一次重要的制度性阻碍：谨慎求证、身份焦虑和急于下结论交织，使一个本应审慎判断的职位过早关闭了调查的门。','拒绝依据当时口述情报采取行动，建议处分警务人员后离会；未记载他获知最终真相后的反应。','矮胖老年将军，怒容明显，随行两名秘书。','维护军政决策的可信度与自己的指挥权威。','先要求解释和证据，受到荒诞感与体面压力影响时会迅速斥退。','军政会议与职责判断；未展示个人作战或实际发动军队攻击。',[(1850,1878,'会议身份与质问'),(1880,1908,'索证、否定与离场'),(1928,1944,'拒绝救援对后续行动的影响')],[('有人要求依据离奇口述调动重大资源','缺乏可交叉核验的实物','会要求证据，不因对方情绪激烈立即相信。'),('场合有外交与下级旁观','自认被荒唐请求损害体面','可能把查证提前变成斥责和处分。'),('出现足够的新证据','原文没有证明其必定固执到底','允许重新评估，不把一次误判写成永远拒绝事实。')],roles=['阶段性对立者'],uncertainties=['没有与敌方勾结证据，也没有个人战斗表现；军职不折算成军队武器归其肉身所有。'])],cast=['mu_lanhua','mu_xiuzhen','gao_xiang','fang_director','sadula','amina'],excluded=[{'name':'丁培、老妇仆人','reason':'事故参与者与受害者，非本书主角；老妇受辱中毒不自动归为反派。'},{'name':'法道尔少校、王警官、五名蛙人','reason':'本书一次性盟友或执行人员；相应组织行动为主角的有条件协助。'},{'name':'赛特、学校女工、参观领队及无名押送者','reason':'一次性学员或执行助手，未有独立人物目标；不能把被木兰花击昏者自动当主要反派。'},{'name':'各国领事武官','reason':'会议背景人物，独立起主导阻碍作用的梅将军另建卡。'}],notes=['“超人”是精英统治集团自称，不表示所有成员拥有超常肉身。火箭燃料尚未研发完成；海底电厂毁灭导致空中平台失电，不作为终局保留的常驻装备。'])
(P/'mulanhua_e.draft.json').write_text(json.dumps(books,ensure_ascii=False,indent=2),encoding='utf-8')
